  .sun{position:absolute;left:174px;top:23px;width:49px;height:49px;background:#da8c2a;clip-path:polygon(50% 0,60% 35%,92% 9%,72% 44%,100% 50%,67% 60%,92% 91%,58% 70%,50% 100%,41% 66%,9% 92%,30% 58%,0 50%,34% 41%,9% 9%,43% 31%)}
  .reader{position:absolute;left:213px;top:39px;width:110px;height:220px}
