  .signup{position:absolute;z-index:4;left:650px;top:-63px;width:300px;min-height:416px;padding:24px;background:#fff;border:1px solid #ddd;border-radius:9px;box-shadow:0 1px 3px #ddd;text-align:center}
  .signup h2{font:20px Georgia,serif;margin:0 0 20px}
  .signup button{display:block;width:100%;height:49px;margin:0 0 13px;border:1px solid #aaa;border-radius:3px;background:white;color:#333}
  .signup .amazon{background:#f5dc7d;border-color:#c3a645}
  .signup .email{background:#321b0d;color:white;border-color:#321b0d}
  .signup small{display:block;color:#888;line-height:19px;font-size:12px}
