  .nav-auth{color:#333;font-size:16px}
  .award-hero{height:384px;position:relative;overflow:hidden}
  .award-hero.y2024{background:#293d2b;color:#fff}
  .award-hero.y2022{height:384px;background:#f5e9bd;color:#c5a23b}
  .award-hero-inner{height:100%;width:820px;margin:auto;display:flex;align-items:center;gap:28px;position:relative}
  .award-badge{width:172px;height:260px;object-fit:contain}
  .hero-copy{width:600px}
  .hero-copy h1{font:italic 43px Georgia,serif;margin:0 0 16px}
  .hero-copy p{font-size:17px;line-height:25px;margin:0 0 22px}
  .view-results{background:#ffdb68;border:0;border-radius:3px;padding:9px 22px;font-size:17px;font-weight:bold;color:#211b11}
