  .y2022 .hero-copy p{color:#888;font-size:16px;margin-top:48px}
  .y2022 .vote-count{display:none}
  .award-content{width:1184px;margin:36px auto 70px;display:grid;grid-template-columns:230px 740px;gap:20px;align-items:start}
  .schedule{border:4px solid #f3d66f;padding:14px 16px 17px;font-size:13px}
  .schedule h3{font-size:14px;margin:0 0 14px}
  .schedule-line{display:flex;justify-content:space-between;line-height:20px;margin-bottom:8px}
  .schedule a{display:block;margin-top:17px}
  .years{margin:20px 16px}
  .years h3{font-size:14px;margin:0 0 13px}
  .years a{display:block;color:#333;line-height:27px;font-size:13px}
  .years a:hover{text-decoration:underline}
  .categories-title{font-weight:bold;margin:12px 0 12px}
  .book-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
  .award-card{height:365px;background:#f3f3f3;text-align:center;padding:8px 12px 6px}
  .award-card h3{font-size:13px;margin:0 0 10px;height:17px}
  .award-card img{width:154px;height:240px;object-fit:contain;display:block;margin:0 auto 6px}
  .want{height:29px;width:100%;border:0;border-radius:3px;background:#48a876;color:#fff;font-weight:bold;text-align:left;padding:0 10px;position:relative}
  .want:after{content:"▾";position:absolute;right:0;top:0;height:29px;width:24px;border-left:1px solid #8dd0aa;text-align:center;line-height:29px}
  .rate{font-size:11px;color:#999;margin:5px 0 0}
  .stars{color:#ccc;letter-spacing:1px;font-size:16px;margin-top:1px}
